       ('questionnement',4,7,'La question spécifique','question_specifique','question_posee','une problématique générique — juste, bien formée, et qui irait à beaucoup d''autres sujets','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('questionnement',4,9,'La question spécifique','question_specifique','question_posee','une problématique générique — juste, bien formée, et qui irait à beaucoup d''autres sujets','rien','« Elle est bonne. **Irait-elle telle quelle à un autre sujet ?** »'),
       ('questionnement',5,1,'L''enjeu','enjeu','enjeu','« c''est une question importante » — l''élève annonce l''importance sans jamais dire ce qu''une réponse changerait','candidats donnés','« Parmi ces quatre, **laquelle dit ce qu''une réponse changerait ?** » — la banque : des phrases qui disent seulement « c''est important » et des phrases qui n''en disent rien ; la bonne énonce ce qu''une réponse changerait.'),
       ('questionnement',5,3,'L''enjeu','enjeu','enjeu','« c''est une question importante » — l''élève annonce l''importance sans jamais dire ce qu''une réponse changerait','candidats donnés','« **Parmi ces quatre ajouts, lequel énonce l''enjeu ?** »'),
       ('questionnement',5,4,'L''enjeu','enjeu','enjeu','« c''est une question importante » — l''élève annonce l''importance sans jamais dire ce qu''une réponse changerait','défaut nommé','« Ici, l''enjeu est **évoqué, pas énoncé.** Surligne la phrase, et dis ce qu''une réponse changerait. »'),
       ('questionnement',5,5,'L''enjeu','enjeu','enjeu','« c''est une question importante » — l''élève annonce l''importance sans jamais dire ce qu''une réponse changerait','défaut nommé','« L''enjeu **n''est pas énoncé.** Dis ce qu''une réponse changerait. »'),
       ('questionnement',5,7,'L''enjeu','enjeu','enjeu','« c''est une question importante » — l''élève annonce l''importance sans jamais dire ce qu''une réponse changerait','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('questionnement',5,9,'L''enjeu','enjeu','enjeu','« c''est une question importante » — l''élève annonce l''importance sans jamais dire ce qu''une réponse changerait','rien','« C''est complet. **L''enjeu y est-il dit, ou seulement annoncé ?** »'),
       ('questionnement',6,1,'Le débat situé','debat_situe','reponses_concurrentes','« on peut en débattre » — l''élève dit qu''il y a débat sans jamais dire quelle est l''autre réponse','candidats donnés','« Quatre lectures. **Laquelle nomme la réponse concurrente, et qu''on peut citer ?** » — la banque : des lectures qui disent « on peut en débattre » et des lectures qui n''en disent rien ; la bonne cite la réponse concurrente.'),
       ('questionnement',6,3,'Le débat situé','debat_situe','reponses_concurrentes','« on peut en débattre » — l''élève dit qu''il y a débat sans jamais dire quelle est l''autre réponse','candidats donnés','« **Parmi ces quatre ajouts, lequel énonce l''autre réponse possible ?** »'),
       ('questionnement',6,4,'Le débat situé','debat_situe','reponses_concurrentes','« on peut en débattre » — l''élève dit qu''il y a débat sans jamais dire quelle est l''autre réponse','défaut nommé','« Le débat est **évoqué sans être situé.** Surligne où, et nomme l''autre réponse. »'),
       ('questionnement',6,5,'Le débat situé','debat_situe','reponses_concurrentes','« on peut en débattre » — l''élève dit qu''il y a débat sans jamais dire quelle est l''autre réponse','défaut nommé','« Tu dis qu''on peut en débattre **sans dire de quoi.** Énonce l''autre réponse. »'),
       ('questionnement',6,7,'Le débat situé','debat_situe','reponses_concurrentes','« on peut en débattre » — l''élève dit qu''il y a débat sans jamais dire quelle est l''autre réponse','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('questionnement',6,9,'Le débat situé','debat_situe','reponses_concurrentes','« on peut en débattre » — l''élève dit qu''il y a débat sans jamais dire quelle est l''autre réponse','rien','« C''est complet. **La réponse concurrente y est-elle citable, ou seulement évoquée ?** »'),
       ('questionnement',7,1,'Le recadrage','recadrage','recadrages','l''énoncé est pris pour argent comptant — aucun de ses termes n''est retravaillé, aucune question cachée n''est mise au jour','candidats donnés','« La question est posée. **Parmi ces quatre, laquelle déplace vraiment l''énoncé, au lieu de le redire autrement ?** »'),
       ('questionnement',7,3,'Le recadrage','recadrage','recadrages','l''énoncé est pris pour argent comptant — aucun de ses termes n''est retravaillé, aucune question cachée n''est mise au jour','candidats donnés','« **Parmi ces quatre questions, laquelle interroge l''énoncé lui-même ?** »'),
       ('questionnement',7,4,'Le recadrage','recadrage','recadrages','l''énoncé est pris pour argent comptant — aucun de ses termes n''est retravaillé, aucune question cachée n''est mise au jour','défaut nommé','« Ici, **l''énoncé est pris tel quel.** Surligne le terme qu''il fallait retravailler. »'),
       ('questionnement',7,5,'Le recadrage','recadrage','recadrages','l''énoncé est pris pour argent comptant — aucun de ses termes n''est retravaillé, aucune question cachée n''est mise au jour','défaut nommé','« L''énoncé **n''est jamais interrogé.** Écris la question qu''il fallait lui poser d''abord. »'),
       ('questionnement',7,7,'Le recadrage','recadrage','recadrages','l''énoncé est pris pour argent comptant — aucun de ses termes n''est retravaillé, aucune question cachée n''est mise au jour','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('questionnement',7,9,'Le recadrage','recadrage','recadrages','l''énoncé est pris pour argent comptant — aucun de ses termes n''est retravaillé, aucune question cachée n''est mise au jour','rien','« C''est complet. **La question elle-même a-t-elle été interrogée quelque part ?** »'),
       ('questionnement',8,1,'Le recadrage verbal','recadrage_verbal','recadrages','un recadrage qui change les mots, pas la question — l''élève a compris qu''il faut questionner sa question, pas encore que le recadrage est un outil','candidats donnés','« Dans trois de ces quatre passages, interroger la problématique ne change rien à ce qu''il faut prouver. **Lequel déplace vraiment ?** »'),
       ('questionnement',8,3,'Le recadrage verbal','recadrage_verbal','recadrages','un recadrage qui change les mots, pas la question — l''élève a compris qu''il faut questionner sa question, pas encore que le recadrage est un outil','candidats donnés','« **Parmi ces quatre, lequel remplace la formule par un vrai déplacement ?** »'),
       ('questionnement',8,4,'Le recadrage verbal','recadrage_verbal','recadrages','un recadrage qui change les mots, pas la question — l''élève a compris qu''il faut questionner sa question, pas encore que le recadrage est un outil','défaut nommé','« Ici la problématique est interrogée **pour la forme** — les mots changent, la question non. Surligne ce qui n''a pas bougé. »'),
       ('questionnement',8,5,'Le recadrage verbal','recadrage_verbal','recadrages','un recadrage qui change les mots, pas la question — l''élève a compris qu''il faut questionner sa question, pas encore que le recadrage est un outil','défaut nommé','« Interroger la problématique **ne déplace rien ici.** Refais-le pour que ça change ce qu''il faut prouver. »'),
       ('questionnement',8,7,'Le recadrage verbal','recadrage_verbal','recadrages','un recadrage qui change les mots, pas la question — l''élève a compris qu''il faut questionner sa question, pas encore que le recadrage est un outil','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('questionnement',8,9,'Le recadrage verbal','recadrage_verbal','recadrages','un recadrage qui change les mots, pas la question — l''élève a compris qu''il faut questionner sa question, pas encore que le recadrage est un outil','rien','« La problématique est interrogée quelque part. **Cela change-t-il quelque chose à ce qu''il faut prouver ensuite ?** »'),
       ('questionnement',9,1,'Le recadrage non tenu','recadrage_non_tenu','recadrages','un recadrage réel, abandonné aussitôt — la suite répond à l''ancienne question','candidats donnés','« La problématique a été reformulée en cours de route. **Parmi ces quatre suites, laquelle répond à la NOUVELLE ?** »'),
       ('questionnement',9,3,'Le recadrage non tenu','recadrage_non_tenu','recadrages','un recadrage réel, abandonné aussitôt — la suite répond à l''ancienne question','candidats donnés','« **Parmi ces quatre suites, laquelle tient la nouvelle problématique ?** »'),
       ('questionnement',9,4,'Le recadrage non tenu','recadrage_non_tenu','recadrages','un recadrage réel, abandonné aussitôt — la suite répond à l''ancienne question','défaut nommé','« La problématique a été reformulée, **mais la suite répond à l''ancienne.** Surligne où elle décroche. »'),
       ('questionnement',9,5,'Le recadrage non tenu','recadrage_non_tenu','recadrages','un recadrage réel, abandonné aussitôt — la suite répond à l''ancienne question','défaut nommé','« Tu as reformulé la problématique, puis **tu es revenu à l''ancienne.** Tiens la nouvelle. »'),
       ('questionnement',9,7,'Le recadrage non tenu','recadrage_non_tenu','recadrages','un recadrage réel, abandonné aussitôt — la suite répond à l''ancienne question','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('questionnement',9,9,'Le recadrage non tenu','recadrage_non_tenu','recadrages','un recadrage réel, abandonné aussitôt — la suite répond à l''ancienne question','rien','« La problématique a bien été reformulée. **La suite lui obéit-elle jusqu''au bout ?** »'),
       ('structure',1,1,'La jointure','jointure_presente','','deux unités se suivent sans que rien ne les relie — la couture est vide, le lecteur saute','candidats donnés','« Parmi ces quatre passages, **lequel relie vraiment les deux paragraphes ?** »'),
       ('structure',1,3,'La jointure','jointure_presente','','deux unités se suivent sans que rien ne les relie — la couture est vide, le lecteur saute','candidats donnés','« **Parmi ces quatre liaisons, laquelle tient ?** »'),
       ('structure',1,4,'La jointure','jointure_presente','','deux unités se suivent sans que rien ne les relie — la couture est vide, le lecteur saute','défaut nommé','« La couture est **vide** entre ces deux blocs. Surligne l''endroit, et dis ce qui aurait dû s''y écrire. »'),
       ('structure',1,5,'La jointure','jointure_presente','','deux unités se suivent sans que rien ne les relie — la couture est vide, le lecteur saute','défaut nommé','« Entre ces deux blocs, **rien ne fait le lien.** Écris-le. »'),
       ('structure',1,7,'La jointure','jointure_presente','','deux unités se suivent sans que rien ne les relie — la couture est vide, le lecteur saute','rien','« Le fil casse quelque part. **Reprends-le.** »'),
       ('structure',1,9,'La jointure','jointure_presente','','deux unités se suivent sans que rien ne les relie — la couture est vide, le lecteur saute','rien','« Ça s''enchaîne. **Une couture est-elle quand même plus faible que les autres ?** »'),
       ('structure',2,1,'La charnière motivée','charniere_motivee','','la charnière existe et n''est pas motivée — elle annonce un passage sans dire ce qui l''appelle','candidats donnés','« Ces quatre passages annoncent la suite. **Lequel dit pourquoi on y passe ?** »'),
       ('structure',2,3,'La charnière motivée','charniere_motivee','','la charnière existe et n''est pas motivée — elle annonce un passage sans dire ce qui l''appelle','candidats donnés','« **Parmi ces quatre passages, lequel dit ce qui appelle la suite ?** »'),
       ('structure',2,4,'La charnière motivée','charniere_motivee','','la charnière existe et n''est pas motivée — elle annonce un passage sans dire ce qui l''appelle','défaut nommé','« À ce tournant, le texte **annonce la suite sans dire ce qui l''appelle.** Dis ce qui manque. »'),
       ('structure',2,5,'La charnière motivée','charniere_motivee','','la charnière existe et n''est pas motivée — elle annonce un passage sans dire ce qui l''appelle','défaut nommé','« Ce tournant **annonce la suite sans dire pourquoi.** Réécris-le pour qu''il le dise. »'),
       ('structure',2,7,'La charnière motivée','charniere_motivee','','la charnière existe et n''est pas motivée — elle annonce un passage sans dire ce qui l''appelle','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',2,9,'La charnière motivée','charniere_motivee','','la charnière existe et n''est pas motivée — elle annonce un passage sans dire ce qui l''appelle','rien','« C''est articulé. **Un tournant annonce-t-il la suite sans dire ce qui l''appelle ?** »'),
       ('structure',3,1,'La charnière formule','charniere_formule','','un « donc », un « ainsi », un « par conséquent » qui ne portent aucun rapport — le mot de liaison tient lieu de liaison','candidats donnés','« Ces quatre phrases commencent par « donc ». **Dans laquelle le « donc » dit-il quelque chose ?** »'),
       ('structure',3,3,'La charnière formule','charniere_formule','','un « donc », un « ainsi », un « par conséquent » qui ne portent aucun rapport — le mot de liaison tient lieu de liaison','candidats donnés','« **Parmi ces quatre mots de liaison, lequel dit le vrai rapport entre les deux idées ?** »'),
       ('structure',3,4,'La charnière formule','charniere_formule','','un « donc », un « ainsi », un « par conséquent » qui ne portent aucun rapport — le mot de liaison tient lieu de liaison','défaut nommé','« Ce « donc » **ne porte aucun rapport.** Surligne-le, et dis ce qui aurait dû le justifier. »'),
       ('structure',3,5,'La charnière formule','charniere_formule','','un « donc », un « ainsi », un « par conséquent » qui ne portent aucun rapport — le mot de liaison tient lieu de liaison','défaut nommé','« Ce mot de liaison est **une formule.** Remplace-le par ce qui relie vraiment. »'),
       ('structure',3,7,'La charnière formule','charniere_formule','','un « donc », un « ainsi », un « par conséquent » qui ne portent aucun rapport — le mot de liaison tient lieu de liaison','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',3,9,'La charnière formule','charniere_formule','','un « donc », un « ainsi », un « par conséquent » qui ne portent aucun rapport — le mot de liaison tient lieu de liaison','rien','« C''est articulé. **Un connecteur y tient-il lieu d''articulation ?** »'),
       ('structure',4,1,'Le bloc relié','bloc_relie','','un bloc est posé à côté des autres sans que sa relation à eux soit nommée — le texte avance par juxtaposition','candidats donnés','« Parmi ces quatre blocs, **lequel dit sa relation à ce qui précède ?** »'),
       ('structure',4,3,'Le bloc relié','bloc_relie','','un bloc est posé à côté des autres sans que sa relation à eux soit nommée — le texte avance par juxtaposition','candidats donnés','« **Parmi ces quatre ouvertures, laquelle nomme la relation du bloc à ce qui précède ?** »'),
       ('structure',4,4,'Le bloc relié','bloc_relie','','un bloc est posé à côté des autres sans que sa relation à eux soit nommée — le texte avance par juxtaposition','défaut nommé','« Ce bloc est **juxtaposé** — sa relation n''est nommée nulle part. Surligne-le. »'),
       ('structure',4,5,'Le bloc relié','bloc_relie','','un bloc est posé à côté des autres sans que sa relation à eux soit nommée — le texte avance par juxtaposition','défaut nommé','« Ce bloc **ne dit pas sa relation** au précédent. Nomme-la. »'),
       ('structure',4,7,'Le bloc relié','bloc_relie','','un bloc est posé à côté des autres sans que sa relation à eux soit nommée — le texte avance par juxtaposition','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',4,9,'Le bloc relié','bloc_relie','','un bloc est posé à côté des autres sans que sa relation à eux soit nommée — le texte avance par juxtaposition','rien','« Ça se tient. **Un paragraphe y est-il posé sans qu''on dise à quoi il s''accroche ?** »'),
       ('structure',5,1,'L''unité de bloc','bloc_unite','','un bloc énumère sans jamais énoncer son idée directrice — le paragraphe-liste','candidats donnés','« Parmi ces quatre paragraphes, **lequel énonce son idée directrice ?** »'),
       ('structure',5,3,'L''unité de bloc','bloc_unite','','un bloc énumère sans jamais énoncer son idée directrice — le paragraphe-liste','candidats donnés','« **Parmi ces quatre phrases, laquelle donne au paragraphe son idée directrice ?** »'),
       ('structure',5,4,'L''unité de bloc','bloc_unite','','un bloc énumère sans jamais énoncer son idée directrice — le paragraphe-liste','défaut nommé','« Ce paragraphe **n''énonce jamais son point** — il énumère. Dis quel était son point. »'),
       ('structure',5,5,'L''unité de bloc','bloc_unite','','un bloc énumère sans jamais énoncer son idée directrice — le paragraphe-liste','défaut nommé','« Ce paragraphe **n''a pas de point énoncé.** Écris-le. »'),
       ('structure',5,7,'L''unité de bloc','bloc_unite','','un bloc énumère sans jamais énoncer son idée directrice — le paragraphe-liste','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',5,9,'L''unité de bloc','bloc_unite','','un bloc énumère sans jamais énoncer son idée directrice — le paragraphe-liste','rien','« C''est correct. **Le point du paragraphe y est-il énoncé, ou seulement devinable ?** »'),
       ('structure',6,1,'La promesse','promesse_presente','','rien n''est annoncé — ni problème posé, ni plan ; le lecteur n''a aucune attente à quoi mesurer la suite','candidats donnés','« Parmi ces quatre introductions, **laquelle annonce quelque chose ?** »'),
       ('structure',6,3,'La promesse','promesse_presente','','rien n''est annoncé — ni problème posé, ni plan ; le lecteur n''a aucune attente à quoi mesurer la suite','candidats donnés','« **Parmi ces quatre ajouts, lequel pose l''annonce ?** »'),
       ('structure',6,4,'La promesse','promesse_presente','','rien n''est annoncé — ni problème posé, ni plan ; le lecteur n''a aucune attente à quoi mesurer la suite','défaut nommé','« Cette introduction **n''annonce rien** — ni problème posé, ni plan. Dis ce qu''il fallait annoncer. »'),
       ('structure',6,5,'La promesse','promesse_presente','','rien n''est annoncé — ni problème posé, ni plan ; le lecteur n''a aucune attente à quoi mesurer la suite','défaut nommé','« Rien n''est **annoncé** ici. Écris l''annonce. »'),
       ('structure',6,7,'La promesse','promesse_presente','','rien n''est annoncé — ni problème posé, ni plan ; le lecteur n''a aucune attente à quoi mesurer la suite','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',6,9,'La promesse','promesse_presente','','rien n''est annoncé — ni problème posé, ni plan ; le lecteur n''a aucune attente à quoi mesurer la suite','rien','« C''est correct. **Une attente y est-elle créée, ou seulement un thème posé ?** »'),
       ('structure',7,1,'Le plan tenu','plan_tenu','','le texte annonce trois étapes et en fait deux, ou les fait dans un autre ordre','candidats donnés','« Parmi ces quatre développements, **lequel tient l''annonce faite en tête ?** »'),
       ('structure',7,3,'Le plan tenu','plan_tenu','','le texte annonce trois étapes et en fait deux, ou les fait dans un autre ordre','candidats donnés','« **Parmi ces quatre reprises, laquelle rétablit l''étape manquante ?** »'),
       ('structure',7,4,'Le plan tenu','plan_tenu','','le texte annonce trois étapes et en fait deux, ou les fait dans un autre ordre','défaut nommé','« Ce texte **ne tient pas son annonce.** Dis quelle étape manque, ou laquelle a changé de place. »'),
       ('structure',7,5,'Le plan tenu','plan_tenu','','le texte annonce trois étapes et en fait deux, ou les fait dans un autre ordre','défaut nommé','« Une étape annoncée **n''est pas réalisée.** Écris-la à sa place. »'),
       ('structure',7,7,'Le plan tenu','plan_tenu','','le texte annonce trois étapes et en fait deux, ou les fait dans un autre ordre','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',7,9,'Le plan tenu','plan_tenu','','le texte annonce trois étapes et en fait deux, ou les fait dans un autre ordre','rien','« Tout y est. **L''ordre annoncé est-il l''ordre suivi ?** »'),
       ('structure',8,1,'La dérive','derive','','un bloc hors annonce, un doublon, ou un retour en arrière — le texte repart là où il était déjà passé','candidats donnés','« Parmi ces quatre blocs, **lequel sort de ce qui était annoncé ?** »'),
       ('structure',8,3,'La dérive','derive','','un bloc hors annonce, un doublon, ou un retour en arrière — le texte repart là où il était déjà passé','candidats donnés','« **Parmi ces quatre coupes, laquelle retire ce qui sort du chemin annoncé, sans perdre de contenu ?** »'),
       ('structure',8,4,'La dérive','derive','','un bloc hors annonce, un doublon, ou un retour en arrière — le texte repart là où il était déjà passé','défaut nommé','« Ce texte **repart là où il était déjà passé.** Surligne l''endroit, et dis lequel des trois c''est : hors annonce, doublon, ou retour en arrière. »'),
       ('structure',8,5,'La dérive','derive','','un bloc hors annonce, un doublon, ou un retour en arrière — le texte repart là où il était déjà passé','défaut nommé','« Ce bloc **sort de l''annonce.** Remets-le dedans, ou retire-le. »'),
       ('structure',8,7,'La dérive','derive','','un bloc hors annonce, un doublon, ou un retour en arrière — le texte repart là où il était déjà passé','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',8,9,'La dérive','derive','','un bloc hors annonce, un doublon, ou un retour en arrière — le texte repart là où il était déjà passé','rien','« Ça se suit. **Le texte revient-il quelque part sur ses pas ?** »'),
       ('structure',9,1,'Le découpage','','decoupage_present','un découpage plaqué — un moment par paragraphe, qui n''épouse pas les articulations réelles du texte','candidats donnés','« Voici quatre découpages de ce texte. **Lequel épouse ses articulations réelles ?** »'),
       ('structure',9,3,'Le découpage','','decoupage_present','un découpage plaqué — un moment par paragraphe, qui n''épouse pas les articulations réelles du texte','candidats donnés','« **Parmi ces quatre déplacements de coupe, lequel rend le découpage conforme ?** »'),
       ('structure',9,4,'Le découpage','','decoupage_present','un découpage plaqué — un moment par paragraphe, qui n''épouse pas les articulations réelles du texte','défaut nommé','« Ce découpage est **plaqué** — un moment par paragraphe. Surligne où il coupe à côté. »'),
       ('structure',9,5,'Le découpage','','decoupage_present','un découpage plaqué — un moment par paragraphe, qui n''épouse pas les articulations réelles du texte','défaut nommé','« Ce découpage **ne suit pas les articulations du texte.** Refais-le. »'),
       ('structure',9,7,'Le découpage','','decoupage_present','un découpage plaqué — un moment par paragraphe, qui n''épouse pas les articulations réelles du texte','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',9,9,'Le découpage','','decoupage_present','un découpage plaqué — un moment par paragraphe, qui n''épouse pas les articulations réelles du texte','rien','« Le découpage tient. **Une coupe y sépare-t-elle seulement la page, sans séparer les idées ?** »'),
       ('structure',10,1,'La fonction des moments','','fonction_moments','une liste de moments sans leur fonction — on dit où ils sont, jamais ce qu''ils font','candidats donnés','« Ce découpage est juste. **Parmi ces quatre lectures, laquelle dit ce que chaque moment FAIT ?** »'),
       ('structure',10,3,'La fonction des moments','','fonction_moments','une liste de moments sans leur fonction — on dit où ils sont, jamais ce qu''ils font','candidats donnés','« **Parmi ces quatre fonctions, laquelle est celle de ce moment ?** »'),
       ('structure',10,4,'La fonction des moments','','fonction_moments','une liste de moments sans leur fonction — on dit où ils sont, jamais ce qu''ils font','défaut nommé','« Ce découpage **liste les moments sans dire leur fonction.** Nomme-les : pose, nuance, réfute, illustre, conclut, précise. »'),
       ('structure',10,5,'La fonction des moments','','fonction_moments','une liste de moments sans leur fonction — on dit où ils sont, jamais ce qu''ils font','défaut nommé','« Ces moments **n''ont pas de fonction nommée.** Donne-la à chacun. »'),
       ('structure',10,7,'La fonction des moments','','fonction_moments','une liste de moments sans leur fonction — on dit où ils sont, jamais ce qu''ils font','rien','« Ça peut être meilleur. **Reprends-le.** »'),
       ('structure',10,9,'La fonction des moments','','fonction_moments','une liste de moments sans leur fonction — on dit où ils sont, jamais ce qu''ils font','rien','« Les fonctions sont nommées. **Une seule est-elle nommée à côté de ce que le moment fait vraiment ?** »'),
       ('synthese',1,1,'Le contresens','','correspond_a','une unité restituée dit autre chose que le texte — pas une omission, une inversion de sens','candidats donnés','« Parmi ces quatre restitutions de cette phrase, **laquelle dit ce que le texte dit ?** »'),
       ('synthese',1,3,'Le contresens','','correspond_a','une unité restituée dit autre chose que le texte — pas une omission, une inversion de sens','candidats donnés','« **Parmi ces quatre reprises, laquelle rétablit ce que le texte disait ?** »'),
       ('synthese',1,4,'Le contresens','','correspond_a','une unité restituée dit autre chose que le texte — pas une omission, une inversion de sens','défaut nommé','« Cette restitution **fait un contresens.** Surligne l''unité, et dis ce que le texte disait. »'),
       ('synthese',1,5,'Le contresens','','correspond_a','une unité restituée dit autre chose que le texte — pas une omission, une inversion de sens','défaut nommé','« Cette unité **dit le contraire du texte.** Corrige-la. »'),
       ('synthese',1,7,'Le contresens','','correspond_a','une unité restituée dit autre chose que le texte — pas une omission, une inversion de sens','rien','« Ça peut être plus fidèle. **Reprends-le.** »'),
       ('synthese',1,9,'Le contresens','','correspond_a','une unité restituée dit autre chose que le texte — pas une omission, une inversion de sens','rien','« C''est fidèle dans l''ensemble. **Une unité y dit-elle un peu autre chose que le texte ?** »'),
       ('synthese',2,1,'La copie verbatim','','operation','la restitution recopie les phrases du texte au lieu de les reformuler — le surlignage tenant lieu de synthèse','candidats donnés','« Parmi ces quatre restitutions, **laquelle reformule au lieu de recopier ?** »'),
       ('synthese',2,3,'La copie verbatim','','operation','la restitution recopie les phrases du texte au lieu de les reformuler — le surlignage tenant lieu de synthèse','candidats donnés','« **Parmi ces quatre reformulations, laquelle rend l''unité sans la recopier ?** »'),
       ('synthese',2,4,'La copie verbatim','','operation','la restitution recopie les phrases du texte au lieu de les reformuler — le surlignage tenant lieu de synthèse','défaut nommé','« Cette restitution **recopie le texte.** Surligne les passages repris mot pour mot. »'),
       ('synthese',2,5,'La copie verbatim','','operation','la restitution recopie les phrases du texte au lieu de les reformuler — le surlignage tenant lieu de synthèse','défaut nommé','« Cette unité est **recopiée.** Dis-la avec tes mots. »'),
       ('synthese',2,7,'La copie verbatim','','operation','la restitution recopie les phrases du texte au lieu de les reformuler — le surlignage tenant lieu de synthèse','rien','« Ça peut être moins collé au texte. **Reprends-le.** »'),
       ('synthese',2,9,'La copie verbatim','','operation','la restitution recopie les phrases du texte au lieu de les reformuler — le surlignage tenant lieu de synthèse','rien','« C''est reformulé. **Une phrase y est-elle reprise telle quelle ?** »'),
       ('synthese',3,1,'La couverture des essentielles','','correspond_a','une thèse essentielle est absente de la restitution — le reste est juste, le cœur manque','candidats donnés','« Parmi ces quatre restitutions, **laquelle ne manque aucune thèse essentielle ?** »'),
       ('synthese',3,3,'La couverture des essentielles','','correspond_a','une thèse essentielle est absente de la restitution — le reste est juste, le cœur manque','candidats donnés','« **Parmi ces quatre ajouts, lequel rétablit la thèse manquante ?** »'),
       ('synthese',3,4,'La couverture des essentielles','','correspond_a','une thèse essentielle est absente de la restitution — le reste est juste, le cœur manque','défaut nommé','« Cette restitution **manque une thèse essentielle.** Dis laquelle, et où elle était. »'),
       ('synthese',3,5,'La couverture des essentielles','','correspond_a','une thèse essentielle est absente de la restitution — le reste est juste, le cœur manque','défaut nommé','« Une thèse **essentielle manque.** Ajoute-la. »'),
       ('synthese',3,7,'La couverture des essentielles','','correspond_a','une thèse essentielle est absente de la restitution — le reste est juste, le cœur manque','rien','« Il manque quelque chose. **Reprends-le.** »'),
       ('synthese',3,9,'La couverture des essentielles','','correspond_a','une thèse essentielle est absente de la restitution — le reste est juste, le cœur manque','rien','« Tout y semble. **Une thèse essentielle y manque-t-elle quand même ?** »'),
       ('synthese',4,1,'L''élagage','','operation','l''exemple est gardé, la thèse est perdue — la restitution retient l''illustration frappante et laisse tomber ce qu''elle illustrait','candidats donnés','« Parmi ces quatre restitutions, **laquelle garde l''idée plutôt que l''exemple ?** »'),
       ('synthese',4,3,'L''élagage','','operation','l''exemple est gardé, la thèse est perdue — la restitution retient l''illustration frappante et laisse tomber ce qu''elle illustrait','candidats donnés','« **Parmi ces quatre coupes, laquelle élague l''illustration sans perdre l''idée ?** »'),
       ('synthese',4,4,'L''élagage','','operation','l''exemple est gardé, la thèse est perdue — la restitution retient l''illustration frappante et laisse tomber ce qu''elle illustrait','défaut nommé','« Cette restitution **garde l''exemple et perd la thèse.** Surligne où, et dis quelle était la thèse. »'),
       ('synthese',4,5,'L''élagage','','operation','l''exemple est gardé, la thèse est perdue — la restitution retient l''illustration frappante et laisse tomber ce qu''elle illustrait','défaut nommé','« Tu as gardé l''exemple et **perdu l''idée.** Rétablis-la, et élague l''exemple. »'),
       ('synthese',4,7,'L''élagage','','operation','l''exemple est gardé, la thèse est perdue — la restitution retient l''illustration frappante et laisse tomber ce qu''elle illustrait','rien','« Ça peut être mieux hiérarchisé. **Reprends-le.** »'),
       ('synthese',4,9,'L''élagage','','operation','l''exemple est gardé, la thèse est perdue — la restitution retient l''illustration frappante et laisse tomber ce qu''elle illustrait','rien','« C''est ramassé. **Un exemple y a-t-il pris la place de ce qu''il illustrait ?** »'),
       ('synthese',5,1,'La mobilisation reliée','','rapports','la restitution est un catalogue — les unités se suivent, aucune n''est prise dans un rapport qui ne soit pas un simple « et puis »','candidats donnés','« Parmi ces quatre restitutions, **laquelle relie les idées autrement que par « et puis » ?** »'),
       ('synthese',5,3,'La mobilisation reliée','','rapports','la restitution est un catalogue — les unités se suivent, aucune n''est prise dans un rapport qui ne soit pas un simple « et puis »','candidats donnés','« **Parmi ces quatre liens, lequel articule vraiment les deux idées ?** »'),
       ('synthese',5,4,'La mobilisation reliée','','rapports','la restitution est un catalogue — les unités se suivent, aucune n''est prise dans un rapport qui ne soit pas un simple « et puis »','défaut nommé','« Cette restitution est **un catalogue** — rien n''y est articulé. Surligne deux unités qui auraient dû l''être. »'),
       ('synthese',5,5,'La mobilisation reliée','','rapports','la restitution est un catalogue — les unités se suivent, aucune n''est prise dans un rapport qui ne soit pas un simple « et puis »','défaut nommé','« Ces unités **se suivent sans se relier.** Articule-les. »'),
       ('synthese',5,7,'La mobilisation reliée','','rapports','la restitution est un catalogue — les unités se suivent, aucune n''est prise dans un rapport qui ne soit pas un simple « et puis »','rien','« Ça peut être moins listé. **Reprends-le.** »'),
       ('synthese',5,9,'La mobilisation reliée','','rapports','la restitution est un catalogue — les unités se suivent, aucune n''est prise dans un rapport qui ne soit pas un simple « et puis »','rien','« C''est ordonné. **Les idées y sont-elles articulées, ou seulement rangées ?** »'),
       ('synthese',6,1,'La relation rendue','','rapports','un rapport du texte n''est pas rendu — ou un rapport est déclaré que le texte ne portait pas','candidats donnés','« Parmi ces quatre articulations, **laquelle est celle que le texte pose ?** »'),
       ('synthese',6,3,'La relation rendue','','rapports','un rapport du texte n''est pas rendu — ou un rapport est déclaré que le texte ne portait pas','candidats donnés','« **Parmi ces quatre rapports, lequel rend celui du texte ?** »'),
       ('synthese',6,4,'La relation rendue','','rapports','un rapport du texte n''est pas rendu — ou un rapport est déclaré que le texte ne portait pas','défaut nommé','« Ce rapport **n''est pas celui du texte.** Dis lequel il pose vraiment. »'),
       ('synthese',6,5,'La relation rendue','','rapports','un rapport du texte n''est pas rendu — ou un rapport est déclaré que le texte ne portait pas','défaut nommé','« Ce rapport **n''est pas dans le texte.** Rétablis celui qui y est. »'),
       ('synthese',6,7,'La relation rendue','','rapports','un rapport du texte n''est pas rendu — ou un rapport est déclaré que le texte ne portait pas','rien','« Un lien sonne faux. **Reprends-le.** »'),
       ('synthese',6,9,'La relation rendue','','rapports','un rapport du texte n''est pas rendu — ou un rapport est déclaré que le texte ne portait pas','rien','« Les rapports y sont. **L''un d''eux est-il inventé ?** »'),
       ('synthese',7,1,'La part intégrative','','operation','la restitution rend chaque unité une par une — rien n''est fusionné, rien n''est monté d''un cran','candidats donnés','« Parmi ces quatre restitutions, **laquelle rassemble ce qui pouvait l''être ?** »'),
       ('synthese',7,3,'La part intégrative','','operation','la restitution rend chaque unité une par une — rien n''est fusionné, rien n''est monté d''un cran','candidats donnés','« **Parmi ces quatre formulations, laquelle fusionne les deux unités sans en perdre ?** »'),
       ('synthese',7,4,'La part intégrative','','operation','la restitution rend chaque unité une par une — rien n''est fusionné, rien n''est monté d''un cran','défaut nommé','« Cette restitution **rend tout un par un.** Surligne deux unités qui pouvaient n''en faire qu''une. »'),
       ('synthese',7,5,'La part intégrative','','operation','la restitution rend chaque unité une par une — rien n''est fusionné, rien n''est monté d''un cran','défaut nommé','« Ces deux unités **pouvaient n''en faire qu''une.** Fusionne-les. »'),
       ('synthese',7,7,'La part intégrative','','operation','la restitution rend chaque unité une par une — rien n''est fusionné, rien n''est monté d''un cran','rien','« Ça peut être plus ramassé. **Reprends-le.** »'),
       ('synthese',7,9,'La part intégrative','','operation','la restitution rend chaque unité une par une — rien n''est fusionné, rien n''est monté d''un cran','rien','« C''est complet. **Quelque chose y pouvait-il être rassemblé et ne l''est pas ?** »'),
       ('synthese',8,1,'L''apport organisateur','','apports','aucun terme de l''élève ne coiffe — tout est rendu, rien n''est nommé d''un mot qui n''était pas dans le texte','candidats donnés','« Parmi ces quatre restitutions, **laquelle trouve un mot qui rassemble plusieurs idées du texte ?** »'),
       ('synthese',8,3,'L''apport organisateur','','apports','aucun terme de l''élève ne coiffe — tout est rendu, rien n''est nommé d''un mot qui n''était pas dans le texte','candidats donnés','« **Parmi ces quatre termes, lequel tient vraiment ces idées ensemble ?** »'),
       ('synthese',8,4,'L''apport organisateur','','apports','aucun terme de l''élève ne coiffe — tout est rendu, rien n''est nommé d''un mot qui n''était pas dans le texte','défaut nommé','« Cette restitution **ne rassemble rien.** Surligne deux idées qu''un même terme aurait pu tenir ensemble. »'),
       ('synthese',8,5,'L''apport organisateur','','apports','aucun terme de l''élève ne coiffe — tout est rendu, rien n''est nommé d''un mot qui n''était pas dans le texte','défaut nommé','« Rien ne **tient ces idées ensemble** ici. Trouve le terme qui les rassemble. »'),
       ('synthese',8,7,'L''apport organisateur','','apports','aucun terme de l''élève ne coiffe — tout est rendu, rien n''est nommé d''un mot qui n''était pas dans le texte','rien','« Ça peut être mieux organisé. **Reprends-le.** »'),
       ('synthese',8,9,'L''apport organisateur','','apports','aucun terme de l''élève ne coiffe — tout est rendu, rien n''est nommé d''un mot qui n''était pas dans le texte','rien','« C''est bien fait. **Un terme y rassemble-t-il plusieurs idées, ou tout est-il rendu à plat ?** »'),
       ('synthese',9,1,'L''apport vide','','apports','un terme coiffant est posé, il ne recouvre rien — il sonne organisateur et ne subsume aucune unité','candidats donnés','« Parmi ces quatre termes qui rassemblent, **lequel recouvre vraiment des idées du texte ?** »'),
       ('synthese',9,3,'L''apport vide','','apports','un terme coiffant est posé, il ne recouvre rien — il sonne organisateur et ne subsume aucune unité','candidats donnés','« **Parmi ces quatre termes, lequel recouvre les idées annoncées ?** »'),
       ('synthese',9,4,'L''apport vide','','apports','un terme coiffant est posé, il ne recouvre rien — il sonne organisateur et ne subsume aucune unité','défaut nommé','« Ce terme **ne recouvre rien.** Dis quelles idées il prétendait rassembler. »'),
       ('synthese',9,5,'L''apport vide','','apports','un terme coiffant est posé, il ne recouvre rien — il sonne organisateur et ne subsume aucune unité','défaut nommé','« Ce terme **ne recouvre rien.** Remplace-le par celui qui rassemble. »'),
       ('synthese',9,7,'L''apport vide','','apports','un terme coiffant est posé, il ne recouvre rien — il sonne organisateur et ne subsume aucune unité','rien','« Ça sonne creux quelque part. **Reprends-le.** »'),
       ('synthese',9,9,'L''apport vide','','apports','un terme coiffant est posé, il ne recouvre rien — il sonne organisateur et ne subsume aucune unité','rien','« Le terme est là. **Recouvre-t-il quelque chose, ou sonne-t-il seulement organisateur ?** »'),
       ('synthese',10,1,'L''apport décoratif','','apports','le terme coiffe justement et ne travaille jamais — il est posé une fois, plus rien ne s''y appuie','candidats donnés','« Parmi ces quatre restitutions, **dans laquelle le terme qui rassemble sert-il encore ensuite ?** »'),
       ('synthese',10,3,'L''apport décoratif','','apports','le terme coiffe justement et ne travaille jamais — il est posé une fois, plus rien ne s''y appuie','candidats donnés','« **Parmi ces quatre suites, laquelle se sert vraiment du terme ?** »'),
       ('synthese',10,4,'L''apport décoratif','','apports','le terme coiffe justement et ne travaille jamais — il est posé une fois, plus rien ne s''y appuie','défaut nommé','« Ce terme est juste, **mais rien ne s''appuie dessus.** Surligne où il aurait dû resservir. »'),
       ('synthese',10,5,'L''apport décoratif','','apports','le terme coiffe justement et ne travaille jamais — il est posé une fois, plus rien ne s''y appuie','défaut nommé','« Ton terme est juste. **Sers-t''en vraiment, au lieu de le poser une seule fois.** »'),
       ('synthese',10,7,'L''apport décoratif','','apports','le terme coiffe justement et ne travaille jamais — il est posé une fois, plus rien ne s''y appuie','rien','« Ça peut aller plus loin. **Reprends-le.** »'),
       ('synthese',10,9,'L''apport décoratif','','apports','le terme coiffe justement et ne travaille jamais — il est posé une fois, plus rien ne s''y appuie','rien','« Le terme rassemble bien. **Le texte s''en ressert-il ensuite, ou l''a-t-il posé une seule fois ?** »'),
       ('synthese',11,1,'L''apport non couvrant','','apports','le terme ne coiffe qu''une seule unité — il est posé comme s''il rassemblait, et il n''étiquette qu''une idée. Deux familles le déclenchent et l''exercice sert les deux : le terme importé du dehors, et le terme tiré du texte mais trop étroit','candidats donnés','« Parmi ces quatre termes, **lequel rassemble ce que le texte dit, sans rien ajouter ?** »'),
       ('synthese',11,3,'L''apport non couvrant','','apports','le terme ne coiffe qu''une seule unité — il est posé comme s''il rassemblait, et il n''étiquette qu''une idée. Deux familles le déclenchent et l''exercice sert les deux : le terme importé du dehors, et le terme tiré du texte mais trop étroit','candidats donnés','« **Parmi ces quatre termes, lequel reste dans ce que le texte dit ?** »'),
       ('synthese',11,4,'L''apport non couvrant','','apports','le terme ne coiffe qu''une seule unité — il est posé comme s''il rassemblait, et il n''étiquette qu''une idée. Deux familles le déclenchent et l''exercice sert les deux : le terme importé du dehors, et le terme tiré du texte mais trop étroit','défaut nommé','« Ce terme **apporte du dehors.** Dis quelle idée il introduit que le texte ne portait pas. »'),
       ('synthese',11,5,'L''apport non couvrant','','apports','le terme ne coiffe qu''une seule unité — il est posé comme s''il rassemblait, et il n''étiquette qu''une idée. Deux familles le déclenchent et l''exercice sert les deux : le terme importé du dehors, et le terme tiré du texte mais trop étroit','défaut nommé','« Ce terme **ajoute au lieu de rassembler.** Remplace-le. »'),
       ('synthese',11,7,'L''apport non couvrant','','apports','le terme ne coiffe qu''une seule unité — il est posé comme s''il rassemblait, et il n''étiquette qu''une idée. Deux familles le déclenchent et l''exercice sert les deux : le terme importé du dehors, et le terme tiré du texte mais trop étroit','rien','« Ça sort du texte quelque part. **Reprends-le.** »'),
       ('synthese',11,9,'L''apport non couvrant','','apports','le terme ne coiffe qu''une seule unité — il est posé comme s''il rassemblait, et il n''étiquette qu''une idée. Deux familles le déclenchent et l''exercice sert les deux : le terme importé du dehors, et le terme tiré du texte mais trop étroit','rien','« Le terme rassemble. **Rassemble-t-il ce que dit le texte, ou autre chose ?** »');

